<?php

declare(strict_types=1);
require dirname(__DIR__,2).'/config/bootstrap.php';
use App\Auth;use App\Database;use App\Services\PaymentService;use App\Services\PaystackService;
$userId=Auth::requireLogin();$reference=trim((string)($_GET['reference']??''));if($reference===''){http_response_code(400);exit('Missing payment reference.');}$pdo=Database::connection();$s=$pdo->prepare('SELECT * FROM payment_intents WHERE reference=:ref AND user_id=:uid LIMIT 1');$s->execute([':ref'=>$reference,':uid'=>$userId]);$intent=$s->fetch();if(!$intent){http_response_code(404);exit('Payment not found.');}$message='Payment is pending verification.';$ok=false;try{$paystack=new PaystackService((string)(getenv('PAYSTACK_SECRET_KEY')?:''));$data=$paystack->verify($reference);if(($data['status']??'')==='success'){$expected=(int)round((float)$intent['amount']*100);if((int)($data['amount']??0)!==$expected||strtoupper((string)($data['currency']??''))!==strtoupper($intent['currency']))throw new RuntimeException('Payment verification mismatch.');(new PaymentService())->completeIntent($reference,(string)($data['id']??$reference),$data);$ok=true;$message='Payment verified and your wallet has been credited.';}else{$message='Payment has not been completed.';}}catch(Throwable $e){$message='Payment could not be verified yet.';}
